+/*
+ * SPDX-FileCopyrightText: 2026 Vibhor <vibhor1102@gmail.com>
+ * SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#pragma once
+
+#include <QHash>
+#include <QString>
+#include <QtMath>
+
+#include <algorithm>
+#include <cmath>
+
+namespace PowerDevil
+{
+
+struct BatteryCharge {
+    int percent = 0;
+    double energy = 0;
+    double energyFull = 0;
+    bool present = false;
+};
+
+inline int aggregateChargePercent(const QHash<QString, BatteryCharge> &batteries)
+{
+    double energy = 0;
+    double energyFull = 0;
+    double percentSum = 0;
+    int count = 0;
+    for (const BatteryCharge &battery : batteries) {
+        if (!battery.present) {
+            continue;
+        }
+        energy += battery.energy;
+        energyFull += battery.energyFull;
+        percentSum += battery.percent;
+        ++count;
+    }
+
+    if (count == 0) {
+        return 0;
+    }
+
+    // For one present battery, use its reported percentage, as the battery applet does.
+    if (count == 1) {
+        return std::clamp(static_cast<int>(percentSum), 0, 100);
+    }
+
+    if (energyFull > 0 && std::isfinite(energy) && std::isfinite(energyFull)) {
+        return qRound(std::clamp(energy / energyFull * 100, 0.0, 100.0));
+    }
+
+    // Some power supplies do not provide energy values (for example, UPSes).
+    return qRound(std::clamp(percentSum / count, 0.0, 100.0));
+}
+
+}
