From 71379f0bac8b9f48071e4473a36a091961d955c9 Mon Sep 17 00:00:00 2001
From: Vibhor Goel <vibhor1102@gmail.com>
Date: Sun, 4 Oct 2026 09:34:10 +0530
Subject: [PATCH 3/5] Recheck battery warnings when AC power is disconnected

Topology changes may arrive while UPower still reports AC power. Recheck
charge when it later reports battery power, including an ordinary unplug
below the warning threshold.

Do not replace an existing critical notification or restart a running
critical countdown, including when its popup has disappeared.
---
 daemon/powerdevilcore.cpp | 5 +++++
 1 file changed, 5 insertions(+)

diff --git a/daemon/powerdevilcore.cpp b/daemon/powerdevilcore.cpp
index 598561bf5..6ea0e4c91 100644
--- a/daemon/powerdevilcore.cpp
+++ b/daemon/powerdevilcore.cpp
@@ -761,6 +761,11 @@ void Core::onAcAdapterStateChanged(BatteryController::AcAdapterState state)
         m_powerCordUnpluggedNotification->setText(i18n("The power cord has been unplugged."));

         m_powerCordUnpluggedNotification->sendEvent();
+
+        // Battery topology changes can arrive before UPower reports that AC power is gone.
+        if (m_notificationsReady && !m_criticalBatteryNotification && !m_criticalBatteryTimer->isActive()) {
+            emitBatteryChargePercentNotification(currentChargePercent(), 1000);
+        }
     }
 }

