+ */
+
+#include "powerdevilcore.h"
+#include "powerdevilenums.h"
+
+#include <PowerDevilGlobalSettings.h>
+#include <Solid/Battery>
+#include <Solid/Device>
+
+#include <KConfigGroup>
+#include <KLocalizedString>
+#include <KNotification>
+#include <KSharedConfig>
+
+#include <QApplication>
+#include <QFile>
+#include <QProcess>
+#include <QSignalSpy>
+#include <QStandardPaths>
+#include <QTemporaryDir>
+#include <QTest>
+#include <QTimer>
+
+namespace PowerDevil
+{
+
+class CoreBatteryTest : public QObject
+{
+    Q_OBJECT
+
+private:
+    static QString udi(const char *name)
+    {
+        return QStringLiteral("/org/kde/solid/fakehw/") + QString::fromLatin1(name);
+    }
+
+    void addBattery(const char *name)
+    {
+        // Notification delivery is not ready during initial device enumeration.
+        const bool notificationsReady = m_core->m_notificationsReady;
+        m_core->m_notificationsReady = false;
+        m_core->m_isProfileActive = false;
+        m_core->onDeviceAdded(udi(name));
+        m_core->m_isProfileActive = true;
+        m_core->m_notificationsReady = notificationsReady;
+    }
+
+    std::unique_ptr<Core> m_core;
+    KSharedConfig::Ptr m_notificationConfig;
+
+private Q_SLOTS:
+    void initTestCase()
+    {
+        // Inspect notification objects without involving popup or sound delivery.
+        m_notificationConfig = KSharedConfig::openConfig(QStringLiteral("powerdevil.notifyrc"), KConfig::NoGlobals);
+        m_notificationConfig->group(QStringLiteral("Event/lowbattery")).writeEntry("Action", QStringLiteral("None"));
+        m_notificationConfig->group(QStringLiteral("Event/criticalbattery")).writeEntry("Action", QStringLiteral("None"));
+        m_notificationConfig->group(QStringLiteral("Event/pluggedin")).writeEntry("Action", QStringLiteral("None"));
+        m_notificationConfig->group(QStringLiteral("Event/unplugged")).writeEntry("Action", QStringLiteral("None"));
+        // Keep the shared overrides in memory without writing configuration to disk.
+        m_notificationConfig->markAsClean();
+    }
+
+    void init()
+    {
+        m_core = std::make_unique<Core>(nullptr);
+        m_core->m_globalSettings = new GlobalSettings(false, false, m_core.get());
+        m_core->m_globalSettings->setBatteryLowLevel(20);
+        m_core->m_globalSettings->setBatteryCriticalLevel(7);
+        m_core->m_globalSettings->setBatteryCriticalAction(0);
+        m_core->m_batteryController = std::make_unique<BatteryController>();
+        m_core->m_lidController = std::make_unique<LidController>();
+        m_core->m_suspendController = std::make_unique<SuspendController>();
+        m_core->m_pendingWakeupEvent = false;
+        m_core->m_notificationsReady = true;
+        m_core->m_currentProfile = QStringLiteral("Battery");
+        m_core->m_isProfileActive = true;
+        m_core->m_criticalBatteryTimer->setSingleShot(true);
+        m_core->m_criticalBatteryTimer->setInterval(60000);
+
+        const QVariantMap properties{{QStringLiteral("OnBattery"), true}};
+        QVERIFY(QMetaObject::invokeMethod(m_core->m_batteryController.get(),
+                                          "onPropertiesChanged",
+                                          Qt::DirectConnection,
+                                          Q_ARG(QString, QStringLiteral("org.freedesktop.UPower")),
+                                          Q_ARG(QVariantMap, properties),
+                                          Q_ARG(QStringList, QStringList())));
+    }
+
+    void cleanup()
+    {
+        const auto lowNotification = m_core->m_lowBatteryNotification;
+        const auto criticalNotification = m_core->m_criticalBatteryNotification;
+        m_core->updateBatteryNotifications(100);
+        m_core.reset();
+        // Run queued callbacks as well as deferred deletion of notifications and helper jobs.
+        QTest::qWait(0);
+        QTRY_VERIFY(!lowNotification && !criticalNotification);
+    }
+
+    void coherentPropertyUpdate()
+    {
+        addBattery("BAT0");
+        addBattery("BAT1");
+        // The backend already holds the new complete snapshot when either signal arrives.
+        m_core->m_batteries[udi("BAT0")] = {21, 6.15, 30, true};
+        QCOMPARE(m_core->currentChargePercent(), 21);
+        QSignalSpy profiles(m_core.get(), &Core::profileChanged);
+
+        Solid::Device device(udi("BAT0"));
+        auto *battery = device.as<Solid::Battery>();
+        QVERIFY(battery);
+        battery->energyChanged(6.0, device.udi());
+        QCOMPARE(m_core->currentChargePercent(), 21);
+        QVERIFY(!m_core->m_lowBatteryNotification);
+        QVERIFY(!m_core->m_criticalBatteryNotification);
+
+        battery->energyFullChanged(29.0, device.udi());
+        QCOMPARE(m_core->currentChargePercent(), 21);
+        QCOMPARE(profiles.count(), 0);
+    }
+
+    void inactiveCriticalCrossing()
+    {
+        addBattery("BAT0");
+        addBattery("BAT1");
+        m_core->m_globalSettings->setBatteryLowLevel(24);
+        m_core->m_globalSettings->setBatteryCriticalLevel(22);
+        m_core->m_globalSettings->setBatteryCriticalAction(static_cast<int>(PowerButtonAction::Sleep));
+        m_core->m_batteries[udi("BAT0")] = {30, 9, 30, true};
+        QCOMPARE(m_core->currentChargePercent(), 25);
+        m_core->m_isProfileActive = false;
+        QSignalSpy profiles(m_core.get(), &Core::profileChanged);
+        Solid::Device device(udi("BAT0"));
+        device.as<Solid::Battery>()->energyChanged(6.0, device.udi());
+        QCOMPARE(m_core->currentChargePercent(), 21);
+        QVERIFY(!m_core->m_isProfileActive);
+        QCOMPARE(profiles.count(), 0);
+        QVERIFY(m_core->m_criticalBatteryNotification);
+        QVERIFY(m_core->m_criticalBatteryTimer->isActive());
+    }
+
+    void inactiveTopologyInsertion()
+    {
+        addBattery("DESIGN");
+        m_core->m_globalSettings->setBatteryLowLevel(24);
+        m_core->m_globalSettings->setBatteryCriticalLevel(22);
+        m_core->m_globalSettings->setBatteryCriticalAction(static_cast<int>(PowerButtonAction::Sleep));
+        m_core->m_isProfileActive = false;
+        QSignalSpy profiles(m_core.get(), &Core::profileChanged);
+        m_core->onDeviceAdded(udi("DEPLETED"));
+        QCOMPARE(m_core->currentChargePercent(), 13);
+        QVERIFY(!m_core->m_isProfileActive);
+        QCOMPARE(profiles.count(), 0);
+        QVERIFY(m_core->m_criticalBatteryNotification);
+        QVERIFY(m_core->m_criticalBatteryTimer->isActive());
+    }
+
+    void designCapacitySignal()
+    {
+        addBattery("DESIGN");
+        addBattery("BAT1");
+        const int previousPercent = m_core->currentChargePercent();
+
+        Solid::Device device(udi("DESIGN"));
+        auto *battery = device.as<Solid::Battery>();
+        QVERIFY(battery);
+        battery->energyFullChanged(battery->energyFullDesign(), device.udi());
+        QCOMPARE(m_core->m_batteries.value(device.udi()).energyFull, 30.0);
+        QCOMPARE(m_core->currentChargePercent(), previousPercent);
+    }
+
+    void removingLastBattery_data()
+    {
+        QTest::addColumn<bool>("critical");
+        QTest::newRow("low warning") << false;
+        QTest::newRow("critical timer") << true;
+    }
+
+    void removingLastBattery()
+    {
+        QFETCH(bool, critical);
+        m_core->m_batteries.insert(udi("REMOVED"), {5, 1, 20, true});
+        m_core->m_currentProfile = QStringLiteral("LowBattery");
+        if (critical) {
+            m_core->m_globalSettings->setBatteryCriticalAction(static_cast<int>(PowerButtonAction::Sleep));
+            m_core->handleCriticalBattery(5);
+            QVERIFY(m_core->m_criticalBatteryTimer->isActive());
+        } else {
+            m_core->handleLowBattery(5);
+        }
+
+        m_core->onDeviceRemoved(udi("REMOVED"));
+        QVERIFY(!m_core->hasSystemBattery());
+        QVERIFY(!m_core->m_lowBatteryNotification);
+        QVERIFY(!m_core->m_criticalBatteryNotification);
+        QVERIFY(!m_core->m_criticalBatteryTimer->isActive());
+        QCOMPARE(m_core->currentProfile(), QStringLiteral("AC"));
+    }
+
+
+};
+
+}
+
+int main(int argc, char **argv)
+{
+    // Keep controller and KAuth D-Bus traffic off the running desktop's buses.
+    QProcess bus;
+    bus.start(QStringLiteral("dbus-daemon"), {QStringLiteral("--session"), QStringLiteral("--nofork"), QStringLiteral("--print-address=1")});
+    if (!bus.waitForStarted() || !bus.waitForReadyRead()) {
+        qCritical("Could not start the test D-Bus daemon");
+        return 1;
+    }
+    const QByteArray address = bus.readLine().trimmed();
+    qputenv("DBUS_SESSION_BUS_ADDRESS", address);
+    qputenv("DBUS_SYSTEM_BUS_ADDRESS", address);
+    QStandardPaths::setTestModeEnabled(true);
+
+    int result;
+    {
+        QApplication application(argc, argv);
+        application.setProperty("org.kde.KActivities.core.disableAutostart", true);
+        qputenv("SOLID_FAKEHW", QFile::encodeName(QFINDTESTDATA("corebatteries.xml")));
+        PowerDevil::CoreBatteryTest test;
+        result = QTest::qExec(&test, argc, argv);
+    }
+    bus.terminate();
+    bus.waitForFinished();
+    return result;
+}
+
